// Who may put executable code on this instance's server.
//
// A module package is JavaScript: staging import()s module.manifest.js,
// models/ and views/ in the API process, and the route loader later runs
// api/index.js there with the global Prisma client and the process env. That
// is instance-wide (every company) code execution, so a company admin must
// never be able to authorize it. Only three sources may:
//   - the platform owner (the instance-level authority, platform-owner.js),
//   - the Module Builder compiler (code generated by this server from a
//     validated ModuleDefinition, never caller-supplied JS),
//   - a package verified against the pinned Runly official catalog key.
// Every staging call must name one; anything else fails closed.
// Spec: docs/audits/RUNLY_PLATFORM_F1A_SECURITY_RESULTS.md (P0-01).

export const MODULE_CODE_AUTHORITY = Object.freeze({
  PLATFORM_OWNER: "platform-owner",
  BUILDER_COMPILER: "builder-compiler",
  RUNLY_OFFICIAL: "runly-official-signature",
});

const AUTHORITIES = new Set(Object.values(MODULE_CODE_AUTHORITY));

export const MODULE_CODE_AUTHORITY_ERROR = "Instalar código de módulos afecta a todas las empresas de la instancia. Solo el propietario de la plataforma puede subir paquetes o instalar módulos que no sean oficiales de Runly.";

export function isModuleCodeAuthority(value) {
  return AUTHORITIES.has(value);
}

// Platform owner only: company admin, system admin role or any permission set is not enough.
export function ownerCodeAuthority(tenant) {
  return tenant?.isPlatformOwner === true ? MODULE_CODE_AUTHORITY.PLATFORM_OWNER : null;
}

// Catalog packages: the pinned official signature, otherwise the platform owner.
export function catalogCodeAuthority({ official, tenant }) {
  return official === true ? MODULE_CODE_AUTHORITY.RUNLY_OFFICIAL : ownerCodeAuthority(tenant);
}

export function moduleCodeAuthorityDenied(c) {
  return c.json({ error: "MODULE_CODE_AUTHORITY_REQUIRED", message: MODULE_CODE_AUTHORITY_ERROR }, 403);
}
